//! The generated tables (`crates/zant-tsx/src/ui_tags/`, one file per tag, and `zant.d.ts`) are
//! checked in and regenerated by the `zant-tsx-tags` / `zant-tsx-dts` binaries.
//! These tests run the binaries the way CI does:
//!
//! ```text
//! cargo run -p zant-tables --bin zant-tsx-tags -- crates/zant-tsx/src/ui_tags
//! cargo run -p zant-tables --bin zant-tsx-tags -- --check crates/zant-tsx/src/ui_tags
//! cargo run -p zant-tables --bin zant-tsx-dts -- crates/zant-tsx/zant.d.ts
//! cargo run -p zant-tables --bin zant-tsx-dts -- --check crates/zant-tsx/zant.d.ts
//! ```

use std::path::{Path, PathBuf};
use std::process::{Command, Output};

fn repo_root() -> PathBuf {
    // crates/zant-tsx → repository root.
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("the repository root")
}

fn table_path() -> PathBuf {
    repo_root().join("crates/zant-tsx/src/ui_tags")
}

fn dts_path() -> PathBuf {
    repo_root().join("crates/zant-tsx/zant.d.ts")
}

fn run(bin: &str, args: &[&str]) -> Output {
    Command::new(bin)
        .args(args)
        .output()
        .unwrap_or_else(|error| panic!("run {bin} {args:?}: {error}"))
}

fn check(bin: &str, args: &[&str]) {
    let output = run(bin, args);
    assert!(
        output.status.success(),
        "{bin} {args:?} failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
}

/// The small scratch directory of one test: `target/tmp/<name>`.
fn scratch(name: &str) -> PathBuf {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../target/tmp")
        .join(name);
    std::fs::create_dir_all(&dir).expect("create the scratch directory");
    dir
}

/// The generated `.rs` files of a table directory, by name.
fn read_table(dir: &Path) -> Vec<(String, String)> {
    let mut files: Vec<(String, String)> = std::fs::read_dir(dir)
        .unwrap_or_else(|error| panic!("read {}: {error}", dir.display()))
        .map(|entry| entry.expect("directory entry").path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "rs"))
        .map(|path| {
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            (name, std::fs::read_to_string(&path).expect("table file"))
        })
        .collect();
    files.sort();
    files
}

#[test]
fn the_tag_generator_is_deterministic() {
    let bin = env!("CARGO_BIN_EXE_zant-tsx-tags");
    let dir = scratch("zant-tsx-tags-deterministic");
    let first = dir.join("first");
    let second = dir.join("second");
    check(bin, &[first.to_str().unwrap()]);
    check(bin, &[second.to_str().unwrap()]);
    let first_files = read_table(&first);
    assert_eq!(
        first_files,
        read_table(&second),
        "two runs must be identical"
    );
    // one file per tag, plus mod / icons / theme / skipped
    assert_eq!(first_files.len(), 38 + 4);
    let module = &first_files
        .iter()
        .find(|(name, _)| name == "mod.rs")
        .expect("mod.rs")
        .1;
    assert!(
        module.contains("38 tags, 474 props, 854 spellings"),
        "the generated header records the table counts"
    );
}

#[test]
fn the_tag_check_mode_passes_for_the_committed_table() {
    let bin = env!("CARGO_BIN_EXE_zant-tsx-tags");
    let path = table_path();
    check(bin, &["--check", path.to_str().unwrap()]);
}

#[test]
fn the_tag_check_mode_rejects_an_outdated_table() {
    let bin = env!("CARGO_BIN_EXE_zant-tsx-tags");
    let dir = scratch("zant-tsx-tags-outdated");
    let table = dir.join("ui_tags");
    check(bin, &[table.to_str().unwrap()]);
    for (stale, why) in [
        ("button.rs", "a changed file"),
        ("removed_tag.rs", "an extra file"),
    ] {
        std::fs::write(table.join(stale), "// stale\n").expect("write the stale file");
        let output = run(bin, &["--check", table.to_str().unwrap()]);
        assert!(!output.status.success(), "{why} fails --check");
        let message = String::from_utf8_lossy(&output.stderr);
        assert!(
            message.contains("out of date"),
            "the diagnostic explains the fix: {message}"
        );
        // writing again restores the table and drops files no tag owns
        check(bin, &[table.to_str().unwrap()]);
        assert!(!table.join("removed_tag.rs").exists());
        check(bin, &["--check", table.to_str().unwrap()]);
    }
}

#[test]
fn the_generated_table_has_the_same_shape_as_the_committed_directory() {
    let bin = env!("CARGO_BIN_EXE_zant-tsx-tags");
    let dir = scratch("zant-tsx-tags-shape");
    let table = dir.join("ui_tags");
    check(bin, &[table.to_str().unwrap()]);
    assert_eq!(read_table(&table), read_table(&table_path()));
}

#[test]
fn the_dts_check_mode_passes_for_the_committed_file() {
    let bin = env!("CARGO_BIN_EXE_zant-tsx-dts");
    let path = dts_path();
    check(bin, &["--check", path.to_str().unwrap()]);
}

#[test]
fn the_dts_snapshot_has_the_expected_shape() {
    let bin = env!("CARGO_BIN_EXE_zant-tsx-dts");
    let dir = scratch("zant-tsx-dts-snapshot");
    let path = dir.join("zant.d.ts");
    check(bin, &[path.to_str().unwrap()]);
    let generated = std::fs::read_to_string(&path).expect("the generated d.ts");
    assert!(generated.starts_with(
        "// Generated by `zant-tsx-dts` from the tag table and dts_api.d.ts. Do not edit.\n\
         // Editor types describe the TSX surface; zant-tsx validates the supported TS subset.\n"
    ));
    // The alias-merged table: the React Native `View` tag and every component
    // function come from `tags::all()`, not from the generated native half.
    assert!(generated.contains("export function View(props: ViewProps): JSX.Element;"));
    assert!(generated.contains("export function Button(props: ButtonProps): JSX.Element;"));
    assert!(generated.contains("export interface Theme {"));
    // `View.style` / `Text.style` close over the props interface itself.
    assert!(
        generated.contains("style?: Partial<Omit<ViewProps, \"style\" | \"key\" | \"children\">>;")
    );
    assert!(generated.ends_with("}\n"));
    let committed = std::fs::read_to_string(dts_path()).expect("the committed d.ts");
    assert_eq!(generated, committed);
}

#[test]
fn the_dts_check_mode_reports_a_missing_file() {
    let bin = env!("CARGO_BIN_EXE_zant-tsx-dts");
    let dir = scratch("zant-tsx-dts-missing");
    let path = dir.join("missing.d.ts");
    let _ = std::fs::remove_file(&path);
    let output = run(bin, &["--check", path.to_str().unwrap()]);
    assert!(!output.status.success(), "a missing file fails --check");
}

/// Every `icon` enumeration of the committed table (reflected props and the
/// hand-written pending tags alike) offers exactly the icons of
/// `zant::core::node::Icon`, so adding an icon reaches all of them.
#[test]
fn every_icon_prop_lists_every_icon() {
    fn collect<'a>(props: &'a [zant_tsx::tags::Prop], out: &mut Vec<&'a zant_tsx::tags::Prop>) {
        for prop in props {
            if prop.name == "icon" && !prop.values.is_empty() {
                out.push(prop);
            }
            collect(&prop.item_props, out);
        }
    }
    let expected: std::collections::BTreeSet<String> = zant::core::node::Icon::ALL
        .iter()
        .map(|icon| format!("{icon:?}"))
        .map(|name| zant_tables_snake(&name))
        .chain(std::iter::once("none".to_owned()))
        .collect();
    let mut props = Vec::new();
    for tag in zant_tsx::tags::all() {
        collect(&tag.props, &mut props);
    }
    assert!(props.len() >= 4, "icon props: {}", props.len());
    for prop in props {
        let values: std::collections::BTreeSet<String> = prop
            .values
            .iter()
            .map(|value| value.rust.to_owned())
            .collect();
        assert_eq!(values, expected, "icon values of `{}`", prop.field);
    }
}

/// `ChevronDown` → `chevron_down`.
fn zant_tables_snake(name: &str) -> String {
    let mut out = String::new();
    for (index, c) in name.chars().enumerate() {
        if c.is_ascii_uppercase() {
            if index > 0 {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}
